#!/usr/bin/env node
// Static validator of The Brain design system (D-005, D-019; DEC-0009 of the harness).
// Checks what the Tailwind theme cannot prevent. It reads the templates, components and styles of the app
// (src/**/*.html, *.ts, *.css), except src/ui/tokens/ and src/ui/docs/ (generated files and the reference document)
// and *.spec.ts files. src/ui/components/ and src/ui/format/ are reviewed (DA-2, D-051).
//
//   node scripts/validate-ui.mjs          reviews src/
//   node scripts/validate-ui.mjs --test   runs the self-tests of the validator
//
// Any other argument is rejected with exit code 1 and src/ is not reviewed.
//
// error level (fails the PR):
//   - Tailwind arbitrary values: bg-[#fff], p-[13px], w-[calc(...)]                  (D-017 to D-019)
//   - opacity modifiers: bg-accent/50, text-ink/80                                   (D-019)
//   - built-in classes without a token: font-bold (and other weights), duration-NNN, delay-NNN,
//     *-px (p-px, gap-px...)                                                         (D-018, D-019)
//   - hand-written colors: #hex, rgb(), rgba(), hsl(), hsla(), oklch()               (D-017)
//   - variables missing from tokens.json, or arbitrary values in parentheses: duration-(--x), w-(calc...)
//   - emoji                                                                          («Contenido y tono»)
// warning level (does not fail; fix it or justify it in the PR):
//   - percent without a space («24.5%» → «24.5 %»), dates with slashes («30/09/2026» → «30-sep-2026»)
//   - possible person name in an action text («Esperando a ...»)                     (D-007, heuristic)
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, resolve, dirname, extname, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
// Variables that exist in the design system (generated by build-tokens.mjs). Only these can be used with the
// Tailwind 4 variable syntax: duration-(--motion-duration-fast), bg-(--color-accent).
const TOKENS = new Set(Object.keys(JSON.parse(readFileSync(join(root, "src/ui/tokens/tokens.flat.json"), "utf8"))));

const FONT_WEIGHTS = "thin|extralight|light|normal|medium|semibold|bold|extrabold|black";
const COLOR_PREFIXES = "bg|text|border|border-[trblxy]|ring|ring-offset|outline|fill|stroke|divide|decoration|placeholder|caret|accent|shadow|from|via|to";
const ERROR_RULES = [
  { id: "arbitrary-value", re: /(?<![\w-])(?:[a-z][\w-]*:)*-?[a-z][\w-]*-\[[^\]\s]+\]/g, message: "valor arbitrario de Tailwind; usa un token de tokens.json o pregunta (D-009)" },
  { id: "opacity", re: new RegExp(`(?<![\\w-])(?:[a-z][\\w-]*:)*(?:${COLOR_PREFIXES})-[a-z][\\w-]*\\/\\d{1,3}(?![\\w.])`, "g"), message: "modificador de opacidad; no existe en el design system (D-019)" },
  { id: "font-weight", re: new RegExp(`(?<![\\w-])(?:[a-z][\\w-]*:)*font-(?:${FONT_WEIGHTS})(?![\\w-])`, "g"), message: "el peso lo fija el estilo tipográfico (text-*), no font-* (D-018, D-019)" },
  { id: "duration", re: /(?<![\w-])(?:[a-z][\w-]*:)*(?:duration|delay)-\d+(?![\w-])/g, message: "duración sin token; usa duration-(--motion-duration-fast) o duration-(--motion-duration-base) (D-016, D-019)" },
  { id: "px", re: /(?<![\w-])(?:[a-z][\w-]*:)*-?(?:p|px|py|pt|pr|pb|pl|ps|pe|m|mx|my|mt|mr|mb|ml|ms|me|gap|gap-x|gap-y|space-x|space-y|inset|top|right|bottom|left|w|h|size)-px(?![\w-])/g, message: "*-px no es un token de espaciado (D-018, D-019)" },
  { id: "hardcoded-color", re: /#[0-9a-fA-F]{3,8}(?![\w-])|\b(?:rgba?|hsla?|oklch|oklab|lab|lch)\(/g, message: "color escrito a mano; usa var(--color-…) o una clase de token (D-017)" },
  { id: "unknown-variable", re: /(?<![\w-])(?:[a-z][\w-]*:)*-?[a-z][\w-]*-\((--[\w-]+)\)/g, filter: (m) => !TOKENS.has(m[1]), message: "variable que no existe en tokens.json (D-009: pregunta antes de inventarla)" },
  { id: "arbitrary-variable", re: /(?<![\w-])(?:[a-z][\w-]*:)*-?[a-z][\w-]*-\((?!--)[^)\s]+\)/g, message: "valor arbitrario entre paréntesis; solo se admiten variables de tokens.json" },
  { id: "emoji", re: /[\u{1F300}-\u{1FAFF}\u{1F000}-\u{1F2FF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}]/gu, message: "emoji en la interfaz («Contenido y tono»)" },
];
const WARNING_RULES = [
  { id: "percent-spacing", re: /\d%/g, textOnly: true, message: "porcentaje sin espacio: «24.5 %»" },
  { id: "slash-date", re: /\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/g, textOnly: true, message: "fecha con barras: el formato es «30-sep-2026»" },
  // The pattern recognizes Spanish UI text, so it stays in Spanish (data).
  { id: "person-name", re: /\b(?:Esperando a|Asignado a|Aprobado por|Enviar a)\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+/g, textOnly: true, message: "posible nombre de persona en una acción o etiqueta (D-007)" },
];

// Parts of a file that get reviewed. In .ts, comments are skipped; in .css and .html, comments too.
function stripComments(text, ext) {
  const blank = (m) => m.replace(/[^\n]/g, " "); // keeps the line count so findings report the right line
  if (ext === ".css") return text.replace(/\/\*[\s\S]*?\*\//g, blank);
  if (ext === ".ts") return text.replace(/\/\*[\s\S]*?\*\//g, blank).replace(/(^|[^:])\/\/.*$/gm, (m, a) => a + blank(m.slice(a.length)));
  if (ext === ".html") return text.replace(/<!--[\s\S]*?-->/g, blank);
  return text;
}
// Approximate visible text: in .html, whatever is not a tag; in .ts, the content of template literals.
function visibleText(text, ext) {
  if (ext === ".html") return text.replace(/<[^>]*>/g, (m) => m.replace(/[^\n]/g, " "));
  if (ext === ".ts") return text.replace(/[^`]*(`[^`]*`)?/g, (m, lit) => (lit ? m.slice(0, m.length - lit.length).replace(/[^\n]/g, " ") + lit.replace(/<[^>]*>/g, (t) => t.replace(/[^\n]/g, " ")) : m.replace(/[^\n]/g, " ")));
  return "";
}
// H6: the CSS literals of a component's styles: (string or array) are not text for people; the percent warning skips them.
const STR = "`[^`]*`|'[^']*'|\"[^\"]*\"";
const STYLES_RE = new RegExp(`\\bstyles\\s*:\\s*(?:\\[\\s*(?:${STR})(?:\\s*,\\s*(?:${STR}))*\\s*,?\\s*\\]|${STR})`, "g");
const blankStyles = (text) => text.replace(STYLES_RE, (m) => m.replace(/[^\n]/g, " "));
const lineOf = (text, i) => text.slice(0, i).split("\n").length;

export function review(text, ext) {
  const clean = stripComments(text, ext);
  const findings = [];
  for (const r of ERROR_RULES) for (const m of clean.matchAll(r.re)) if (!r.filter || r.filter(m)) findings.push({ level: "error", id: r.id, line: lineOf(clean, m.index), sample: m[0], message: r.message });
  const visible = visibleText(ext === ".ts" ? blankStyles(clean) : clean, ext);
  for (const r of WARNING_RULES) for (const m of visible.matchAll(r.re)) findings.push({ level: "warning", id: r.id, line: lineOf(visible, m.index), sample: m[0], message: r.message });
  return findings.sort((a, b) => a.line - b.line);
}

// Whether a file is reviewed (path relative to the repo root, with /). DA-2: the design system pieces and formats are
// reviewed; its generated tokens and its reference document are not; neither are tests.
export function isReviewed(relPath) {
  const rel = relPath.split("\\").join("/");
  if (rel.endsWith(".spec.ts")) return false;
  if (rel.startsWith("src/ui/tokens/") || rel.startsWith("src/ui/docs/")) return false;
  return true;
}

function listFiles(dir) {
  const out = [];
  for (const n of readdirSync(dir)) {
    const p = join(dir, n);
    const rel = relative(root, p).split(sep).join("/");
    if (n === "node_modules") continue;
    if (statSync(p).isDirectory()) out.push(...listFiles(p));
    else if ([".html", ".ts", ".css"].includes(extname(n)) && isReviewed(rel)) out.push(p);
  }
  return out;
}

function selfTest() {
  const cases = [
    // [text, ext, expected ids (in order, without repeats)]
    ['<div class="bg-[#ff0000] p-[13px]"></div>', ".html", ["arbitrary-value", "hardcoded-color"]],
    ['<div class="bg-accent/50 hover:text-ink/80"></div>', ".html", ["opacity"]],
    ['<span class="font-bold duration-150 p-px"></span>', ".html", ["duration", "font-weight", "px"]],
    [".x{color:rgb(0,0,0)}", ".css", ["hardcoded-color"]],
    ["<p>Listo 🚀</p>", ".html", ["emoji"]],
    ["<td>24.5%</td><td>30/09/2026</td>", ".html", ["slash-date", "percent-spacing"]],
    ["<button>Esperando a Óscar</button>", ".html", ["person-name"]],
    ['<div class="bg-surface text-ink p-5 rounded-full text-micro duration-(--motion-duration-fast) shadow-card"></div>', ".html", []],
    ['<div class="duration-(--motion-duration-lenta) bg-(--color-azul)"></div>', ".html", ["unknown-variable"]],
    ['<div class="w-(calc(100%-1px))"></div>', ".html", ["arbitrary-variable"]],
    ['/* #ffffff en un comentario */ .x{color:var(--color-ink)}', ".css", []],
    ["// rgb( en comentario\nconst a = 10 / 2;", ".ts", []],
    ['<td>24.5 %</td><td>30-sep-2026</td><button>Esperando aprobación</button>', ".html", []],
    ["const t = `<p>${'{'}x{'}'} 12%</p>`;", ".ts", ["percent-spacing"]],
  ];
  let failures = 0;
  for (const [text, ext, expected] of cases) {
    const actual = [...new Set(review(text, ext).map((h) => h.id))].sort();
    const ok = JSON.stringify(actual) === JSON.stringify([...expected].sort());
    if (!ok) { failures++; console.error(`FALLA ${JSON.stringify(text)} → ${actual.join(", ") || "(nada)"}; se esperaba ${expected.join(", ") || "(nada)"}`); }
  }
  console.log(failures ? `validate-ui: ${failures} prueba(s) fallaron de ${cases.length}` : `validate-ui: ${cases.length} pruebas correctas`);
  process.exitCode = failures ? 1 : 0;
}

function reviewSrc() {
  let errorCount = 0, warningCount = 0;
  for (const p of listFiles(join(root, "src"))) {
    const rel = relative(root, p).split(sep).join("/");
    for (const h of review(readFileSync(p, "utf8"), extname(p))) {
      console.log(`${h.level === "error" ? "ERROR" : "AVISO"}  ${rel}:${h.line}  ${h.sample}  · ${h.message}`);
      h.level === "error" ? errorCount++ : warningCount++;
    }
  }
  console.log(`validate-ui: ${errorCount} error(es), ${warningCount} aviso(s)`);
  process.exitCode = errorCount ? 1 : 0;
}

// The guard keeps an import from the tests from running anything.
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.length === 0) reviewSrc();
  else if (args.length === 1 && args[0] === "--test") selfTest();
  else {
    // Any other argument is rejected and src/ is not reviewed.
    const legacy = args.includes("--prueba") ? "La opción --prueba ya no existe; usa --test." : `Argumento no reconocido: ${args.join(" ")}.`;
    process.stderr.write(`${legacy}\nUso: node scripts/validate-ui.mjs [--test]\n`);
    process.exitCode = 1;
  }
}
